import{_ as i,o as t,c as s,ae as a}from"./chunks/framework.Czhw_PXq.js";const m=JSON.parse('{"title":"🎨 UX Heuristics & Accessibility Policy - TenderCheck AI","description":"","frontmatter":{},"headers":[],"relativePath":"standards/ux_accessibility_policy.md","filePath":"standards/ux_accessibility_policy.md"}'),r={name:"standards/ux_accessibility_policy.md"};function n(o,e,l,c,d,u){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="🎨-ux-heuristics-accessibility-policy-tendercheck-ai" tabindex="-1">🎨 UX Heuristics &amp; Accessibility Policy - TenderCheck AI <a class="header-anchor" href="#🎨-ux-heuristics-accessibility-policy-tendercheck-ai" aria-label="Permalink to &quot;🎨 UX Heuristics &amp; Accessibility Policy - TenderCheck AI&quot;">​</a></h1><h2 id="_1-nielsen-s-ux-heuristics" tabindex="-1">1. Nielsen&#39;s UX Heuristics <a class="header-anchor" href="#_1-nielsen-s-ux-heuristics" aria-label="Permalink to &quot;1. Nielsen&#39;s UX Heuristics&quot;">​</a></h2><p>[cite_start]The system must follow Jakob Nielsen&#39;s usability principles to ensure a seamless experience[cite: 158, 681]:</p><ul><li><strong>Visibility of System Status</strong>: Use skeleton loaders, progress bars, and &quot;Thinking...&quot; animations to inform the user during PDF processing or AI analysis.</li><li>[cite_start]<strong>User Control and Freedom</strong>: Implement &quot;Undo&quot; actions for reversible tasks (like deleting an analysis) and provide easy resets[cite: 159, 161].</li><li>[cite_start]<strong>Error Prevention &amp; Recovery</strong>: Use toast notifications and clear error messages that explain how to fix issues (e.g., &quot;File too large&quot;)[cite: 159, 161].</li><li>[cite_start]<strong>Consistency &amp; Standards</strong>: Maintain a stable layout and explicit image aspect ratios to prevent Cumulative Layout Shift (CLS).</li></ul><h2 id="_2-accessibility-wcag-2-1-aa" tabindex="-1">2. Accessibility (WCAG 2.1 AA) <a class="header-anchor" href="#_2-accessibility-wcag-2-1-aa" aria-label="Permalink to &quot;2. Accessibility (WCAG 2.1 AA)&quot;">​</a></h2><p>[cite_start]The application must be usable by everyone, following international accessibility standards[cite: 153, 681]:</p><ul><li><strong>Keyboard Navigation</strong>: Full mouseless control must be supported (Tab, Enter, Escape, and arrow keys).</li><li><strong>Screen Reader Support</strong>: All interactive elements must have descriptive ARIA labels, roles, and linked labels.</li><li>[cite_start]<strong>Visual Clarity</strong>: Ensure high-contrast text and clearly visible focus indicators for navigated elements[cite: 156].</li></ul><h2 id="_3-performance-perception" tabindex="-1">3. Performance &amp; Perception <a class="header-anchor" href="#_3-performance-perception" aria-label="Permalink to &quot;3. Performance &amp; Perception&quot;">​</a></h2><ul><li>[cite_start]<strong>Perceived Speed</strong>: Correlate user perception with real performance metrics, ensuring feedback is provided in less than 100ms for optimistic UI updates[cite: 209, 682].</li><li><strong>Lazy Loading</strong>: Use progressive page loading and code splitting to ensure an instant startup experience.</li></ul>',9)])])}const h=i(r,[["render",n]]);export{m as __pageData,h as default};
